method add(lst: seq<int>) returns (result: int)
    requires |lst| > 0 // lst must be a non-empty list
    ensures result == SumEvenAtOddIndices(lst) // result is the sum of even elements at odd indices
{
    var sum := 0;
    var i := 1; // start at the first odd index
    while i < |lst| // iterate over odd indices
        invariant 0 <= i <= |lst| // i must be within the bounds of lst
        invariant sum == SumEvenAtOddIndices(lst[..i]) // sum is the sum of even elements at odd indices up to i
    {
        if lst[i] % 2 == 0 {
            sum := sum + lst[i]; // add to sum if element is even
        }
        i := i + 2; // move to the next odd index
    }
    return sum; // return the calculated sum
}

method SumEvenAtOddIndices(lst: seq<int>) returns (sum: int)
    decreases |lst|
{
    // This is a helper method to calculate the sum of even elements at odd indices
    var total := 0;
    var idx := 1; // start at the first odd index
    while idx < |lst|
        invariant 0 <= idx <= |lst| // idx must be within the bounds of lst
        invariant total == SumEvenAtOddIndices(lst[..idx]) // total is the sum of even elements at odd indices up to idx
    {
        if lst[idx] % 2 == 0 {
            total := total + lst[idx]; // add to total if element is even
        }
        idx := idx + 2; // move to the next odd index
    }
    return total; // return the calculated total
}
